import{_ as n,C as s,o as t,c as p,a2 as o,b as i,w as d,a as r,E as a,a3 as l}from"./chunks/framework.CDA9RsCr.js";const f=JSON.parse('{"title":"后端架构","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/backend.md","filePath":"architecture/backend.md","lastUpdated":1794581028000}'),E={name:"architecture/backend.md"};function A(h,e,m,v,u,S){const c=s("Mermaid");return t(),p("div",null,[e[2]||(e[2]=o('<h1 id="后端架构" tabindex="-1">后端架构 <a class="header-anchor" href="#后端架构" aria-label="Permalink to &quot;后端架构&quot;">​</a></h1><h2 id="入口-main-go" tabindex="-1">入口 main.go <a class="header-anchor" href="#入口-main-go" aria-label="Permalink to &quot;入口 main.go&quot;">​</a></h2><p><code>application.New</code> 注册一个服务 <code>application.NewService(app.New())</code>，内嵌前端 dist 与应用图标，创建 1200×800 webview 窗口（URL <code>/</code>）。同时把 <code>Transport</code> 换成 <code>devbridge.New(appSvc)</code>，这样桌面窗口走 Wails IPC、浏览器标签页走 HTTP 桥接。</p>',3)),(t(),i(l,null,{default:d(()=>[a(c,{id:"mermaid-9",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20M%20as%20main.go%0A%20%20%20%20participant%20A%20as%20application%0A%20%20%20%20participant%20AS%20as%20AppService%0A%20%20%20%20participant%20BR%20as%20devbridge.Transport%0A%20%20%20%20participant%20FS%20as%20%E5%89%8D%E7%AB%AF%20dist%0A%0A%20%20%20%20M-%3E%3EA%3A%20application.New(Options%7BServices%2C%20Assets%2C%20Transport%7D)%0A%20%20%20%20A-%3E%3EA%3A%20%E5%86%85%E5%B5%8C%20frontend%2Fdist%20%E4%B8%8E%20appicon%0A%20%20%20%20A-%3E%3EAS%3A%20ServiceStartup%0A%20%20%20%20AS-%3E%3EAS%3A%20%E5%8A%A0%E8%BD%BD%20config.json%20%2F%20state.json%0A%20%20%20%20AS-%3E%3EAS%3A%20%E6%9E%84%E9%80%A0%20wailsEmitter%EF%BC%8C%E6%B3%A8%E5%85%A5%20live%2Fprofile%0A%20%20%20%20A-%3E%3EBR%3A%20ServeAssets%EF%BC%88%E4%BB%85%E5%9C%A8%E6%8C%82%20Vite%20%E6%97%B6%E5%90%AF%E5%8A%A8%20%3A9246%EF%BC%89%0A%20%20%20%20A-%3E%3EFS%3A%20%E5%88%9B%E5%BB%BA%201200%C3%97800%20webview%20%E7%AA%97%E5%8F%A3%20(URL%20%2F)%0A%20%20%20%20Note%20over%20A%2CFS%3A%20%E8%BF%90%E8%A1%8C%E6%9C%9F%EF%BC%9A%E5%89%8D%E7%AB%AF%E7%BB%8F%E7%BB%91%E5%AE%9A%E6%88%96%20%2Fapi%20%E8%B0%83%E7%94%A8%E5%90%8C%E4%B8%80%E6%89%B9%20service%0A%20%20%20%20A-%3E%3EAS%3A%20ServiceShutdown%0A%20%20%20%20AS-%3E%3EAS%3A%20%E5%81%9C%E6%AD%A2%E5%BC%B9%E5%B9%95%20feed%20%E4%B8%8E%E6%8A%BD%E5%A5%96%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p><code>ApplicationShouldTerminateAfterLastWindowClosed</code> 在设置了 <code>FRONTEND_DEVSERVER_URL</code> 时返回 false，让进程（以及浏览器桥接）在 Vite 调试期间继续存活。</p><h2 id="app-层-wails-边界" tabindex="-1">app 层（Wails 边界） <a class="header-anchor" href="#app-层-wails-边界" aria-label="Permalink to &quot;app 层（Wails 边界）&quot;">​</a></h2><p><code>AppService</code> 是暴露给前端的唯一服务，持有六个 service 与 <code>app *application.App</code>：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>职责</th></tr></thead><tbody><tr><td><code>auth</code></td><td><code>*service.AuthService</code></td><td>登录、账号信息、Cookie 持久化</td></tr><tr><td><code>live</code></td><td><code>*service.LiveLotteryService</code></td><td>抽奖运行态、参与者池、开奖</td></tr><tr><td><code>danmaku</code></td><td><code>*service.DanmakuFeedService</code></td><td>单房间实时弹幕流</td></tr><tr><td><code>emote</code></td><td><code>*service.EmoteService</code></td><td>表情映射表</td></tr><tr><td><code>profile</code></td><td><code>*service.ProfileService</code></td><td>Profile、频道、背景、历史</td></tr><tr><td><code>room</code></td><td><code>*service.RoomService</code></td><td>房间元信息与播放地址</td></tr></tbody></table><ul><li><code>ServiceStartup</code>：加载 <code>~/.luckydraw/config.json</code> 与 <code>state.json</code>，用 <code>application.Get()</code> 拿到 app，构造 <code>wailsEmitter</code> 并注入 <code>live</code>/<code>profile</code>（<code>auth</code> 不需要事件）。</li><li><code>ServiceShutdown</code>：先停 <code>danmaku</code>，再停 <code>live</code>。</li><li><code>ServiceName</code> 返回 <code>&quot;App&quot;</code>。</li></ul>',5)),(t(),i(l,null,{default:d(()=>[a(c,{id:"mermaid-119",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20FE%5B%22%E5%89%8D%E7%AB%AF%20(webview)%22%5D%0A%20%20%20%20%20%20%20%20UI%5BReact%20%E7%BB%84%E4%BB%B6%20%2F%20hooks%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20APP%5B%22internal%2Fapp%20%C2%B7%20Wails%20%E8%BE%B9%E7%95%8C%22%5D%0A%20%20%20%20%20%20%20%20AS%5B%22AppService%3Cbr%2F%3E%E8%96%84%E5%A7%94%E6%89%98%22%5D%0A%20%20%20%20%20%20%20%20WE%5B%22wailsEmitter%3Cbr%2F%3E%E5%AE%9E%E7%8E%B0%20event.Emitter%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SVC%5B%22internal%2Fservice%20%C2%B7%20%E7%BA%AF%E4%B8%9A%E5%8A%A1%22%5D%0A%20%20%20%20%20%20%20%20Auth%5BAuthService%5D%0A%20%20%20%20%20%20%20%20Live%5BLiveLotteryService%5D%0A%20%20%20%20%20%20%20%20Dm%5BDanmakuFeedService%5D%0A%20%20%20%20%20%20%20%20Emote%5BEmoteService%5D%0A%20%20%20%20%20%20%20%20Prof%5BProfileService%5D%0A%20%20%20%20%20%20%20%20Room%5BRoomService%5D%0A%20%20%20%20end%0A%0A%20%20%20%20UI%20--%20%22AppService.*%20%2F%20%2Fapi%2F*%22%20--%3E%20AS%0A%20%20%20%20AS%20--%3E%20Auth%0A%20%20%20%20AS%20--%3E%20Live%0A%20%20%20%20AS%20--%3E%20Dm%0A%20%20%20%20AS%20--%3E%20Prof%0A%20%20%20%20AS%20--%3E%20Room%0A%20%20%20%20Dm%20--%3E%20Emote%0A%20%20%20%20Live%20--%20%22emitter.Emit%20live%3Auser_join%22%20--%3E%20WE%0A%20%20%20%20Prof%20--%20%22emitter.Emit%20profile%3Aswitched%2Fcreated%22%20--%3E%20WE%0A%20%20%20%20WE%20-.%20%22application.Event.Emit%22%20.-%3E%20UI%0A"})]),fallback:d(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p><code>wailsEmitter</code> 实现 <code>event.Emitter</code>，委托 <code>application.App.Event.Emit</code>；service 全程不 import Wails。</p><h2 id="service-层-纯业务" tabindex="-1">service 层（纯业务） <a class="header-anchor" href="#service-层-纯业务" aria-label="Permalink to &quot;service 层（纯业务）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>依赖</th><th>说明</th></tr></thead><tbody><tr><td><code>AuthService</code></td><td><code>*bili.Client</code>、<code>*config.Config</code>、configPath</td><td>启动时用已存 Cookie 校验；<code>-101</code>/<code>-400</code> 时清空并落盘</td></tr><tr><td><code>LiveLotteryService</code></td><td><code>*live.LiveLottery</code>、<code>Emitter</code>、<code>func() *bili.Client</code></td><td>连接房间、开关抽奖、发 <code>live:user_join</code></td></tr><tr><td><code>DanmakuFeedService</code></td><td><code>*bili.Client</code>、<code>*EmoteService</code></td><td>单房间弹幕采集，环形缓冲 200 条，带游标</td></tr><tr><td><code>EmoteService</code></td><td><code>*bili.Client</code></td><td>拉取回复表情 + 直播间表情，6 小时缓存</td></tr><tr><td><code>ProfileService</code></td><td><code>*config.RuntimeState</code>、statePath、<code>Emitter</code></td><td>Profile CRUD、频道、背景、历史（每配置上限 100 条）</td></tr><tr><td><code>RoomService</code></td><td><code>func() *bili.Client</code></td><td>房间信息与播放地址，45 秒缓存</td></tr></tbody></table><p>几个值得记住的实现点：</p><ul><li><strong>弹幕采集与抽奖是两条独立链路</strong>：<code>DanmakuFeedService</code> 只服务右侧弹幕面板，按房间单独连接；<code>LiveLotteryService</code> 为参与池建立自己的连接。面板切房间不会影响正在跑的抽奖。</li><li><strong>弹幕缓冲用游标</strong>：前端带 <code>since</code> 轮询，服务端只返回游标之后的行，避免重复渲染。</li><li><strong>表情索引在服务端合并</strong>：先拉全站回复表情，再叠加当前直播间表情；前端只负责把 <code>[名称]</code> token 映射成图片。</li><li><strong>历史写入在 <code>app</code> 层</strong>：<code>AppService.DrawWinners</code> 拿到结果后调用 <code>profile.AddHistory</code>，失败原因存进 <code>lastHistoryError</code> 由前端一次性取走。</li></ul><h2 id="event-配置" tabindex="-1">event / 配置 <a class="header-anchor" href="#event-配置" aria-label="Permalink to &quot;event / 配置&quot;">​</a></h2><ul><li><code>event.Emitter.Emit(name string, data ...any) bool</code>，由 <code>app.wailsEmitter</code> 实现。</li><li>事件：<code>live:user_join</code>（新参与者）、<code>profile:switched</code>、<code>profile:created</code>。</li></ul><table tabindex="0"><thead><tr><th>类型</th><th>内容</th><th>文件</th></tr></thead><tbody><tr><td><code>Config</code></td><td><code>{Cookie}</code></td><td><code>~/.luckydraw/config.json</code></td></tr><tr><td><code>RuntimeState</code></td><td><code>{Profiles, ActiveProfile}</code></td><td><code>~/.luckydraw/state.json</code></td></tr><tr><td><code>ProfileConfig</code></td><td><code>{ID, Name, BackgroundImage, WatchedRooms, Keyword, WinnerCount, History}</code></td><td>state.json 内</td></tr><tr><td><code>HistoryRecord</code></td><td><code>{ID, Keyword, WinnerCount, Time, Winners}</code></td><td>state.json 内</td></tr></tbody></table><p>两个文件都以 <code>0600</code> 写入、目录 <code>0700</code>。<code>migrateOldState</code> 兼容只有单套配置的旧格式。</p><h2 id="live-bili-login" tabindex="-1">live / bili / login <a class="header-anchor" href="#live-bili-login" aria-label="Permalink to &quot;live / bili / login&quot;">​</a></h2><ul><li><code>bili</code>：HTTP 客户端 + <code>SignWBI</code>。<code>GetMyInfo</code> 返回账号信息；WBI 密钥取自 <code>web-interface/nav</code> 并缓存。</li><li><code>live</code>： <ul><li><code>types.go</code> 协议常量与数据结构（16 字节包头、op 2/3/5/7/8）。</li><li><code>protocol.go</code> 组包 / 解包（含 zlib 压缩体）。</li><li><code>room_auth.go</code> 取房间信息与弹幕主机（WBI 签名，<code>wss_port</code> 优先）。</li><li><code>parse.go</code> 解析 <code>DANMU_MSG</code>、进场 / 关注消息与表情 token。</li><li><code>client.go</code> 连接、鉴权、心跳、重连退避。</li><li><code>lottery.go</code> 参与者池（按 UID 去重）与 Fisher-Yates 开奖。</li></ul></li><li><code>login</code>：扫码流程 <code>GetQRCode</code> / <code>CheckQRCodeStatus</code>，状态码 <code>0</code> 成功、<code>86038</code> 过期、<code>86090</code> 已扫描待确认。</li></ul><p>握手要点：<code>getDanmuInfo</code> 需要 WBI 签名（<code>w_rid</code> / <code>wts</code>）；握手包必须带登录 <code>uid</code>、<code>key</code> 与 <code>buvid3</code>（Cookie 里没有时从 <code>frontend/finger/spi</code> 取），否则 B 站会打码昵称并把 <code>uid</code> 归零，导致所有观众被合并成同一个人。</p><h2 id="浏览器桥接-internal-devbridge" tabindex="-1">浏览器桥接 internal/devbridge <a class="header-anchor" href="#浏览器桥接-internal-devbridge" aria-label="Permalink to &quot;浏览器桥接 internal/devbridge&quot;">​</a></h2><p><code>Transport</code> 包住 Wails 默认的 <code>HTTPTransport</code>，额外提供一层 JSON API：</p><table tabindex="0"><thead><tr><th>路由</th><th>方法</th><th>对应能力</th></tr></thead><tbody><tr><td><code>/api/session</code></td><td>GET</td><td>登录态与账号信息</td></tr><tr><td><code>/api/login</code>、<code>/api/login/qr</code></td><td>POST</td><td>凭证登录、扫码登录</td></tr><tr><td><code>/api/logout</code></td><td>POST</td><td>登出</td></tr><tr><td><code>/api/qr</code>、<code>/api/qr/status</code></td><td>GET</td><td>二维码与轮询状态</td></tr><tr><td><code>/api/rooms</code></td><td>GET / POST / DELETE</td><td>列出、添加、移除频道</td></tr><tr><td><code>/api/rooms/info</code>、<code>/api/rooms/play</code></td><td>GET</td><td>房间信息、播放地址</td></tr><tr><td><code>/api/lottery/connect</code>、<code>/start</code>、<code>/stop</code>、<code>/draw</code></td><td>POST</td><td>连接、开始、停止、开奖</td></tr><tr><td><code>/api/lottery/status</code></td><td>GET</td><td>运行态与参与人数（兼作桥接探活）</td></tr><tr><td><code>/api/lottery/history-error</code></td><td>GET</td><td>取走并清空最近一次历史写入错误</td></tr><tr><td><code>/api/danmaku/watch</code></td><td>POST</td><td>订阅某房间弹幕</td></tr><tr><td><code>/api/danmaku</code></td><td>GET / DELETE</td><td>按 <code>since</code> 拉取、停止订阅</td></tr><tr><td><code>/api/danmaku/emotes</code></td><td>GET</td><td>表情映射</td></tr><tr><td><code>/api/clipboard</code></td><td>POST</td><td>系统剪贴板兜底</td></tr></tbody></table><p><code>APIHandler()</code> 把这套路由单独暴露出来，<code>cmd/devbridge</code> 直接挂载它，因此独立二进制与 Wails 开发传输层的行为完全一致。桥接只在 <code>FRONTEND_DEVSERVER_URL</code> 非空时监听 <code>127.0.0.1:9246</code>，并带 20 次重试以容忍上一次进程尚未释放端口。</p><h2 id="前端可见方法" tabindex="-1">前端可见方法 <a class="header-anchor" href="#前端可见方法" aria-label="Permalink to &quot;前端可见方法&quot;">​</a></h2><p><code>AppService</code> 暴露的全部方法，前端既可通过生成绑定调用，也可经 <code>/api</code> 访问对应路由。</p><table tabindex="0"><thead><tr><th>方法</th><th>领域</th><th>说明</th></tr></thead><tbody><tr><td><code>Login</code> / <code>LoginWithQRCode</code></td><td>auth</td><td>校验并持久化 Cookie</td></tr><tr><td><code>GetQRCode</code> / <code>CheckQRCodeStatus</code></td><td>auth</td><td>二维码生成与轮询</td></tr><tr><td><code>IsLoggedIn</code> / <code>GetAccountInfo</code> / <code>Logout</code></td><td>auth</td><td>会话状态与登出</td></tr><tr><td><code>ConnectLiveRooms</code> / <code>StartLiveLottery</code> / <code>StopLiveLottery</code></td><td>live</td><td>抽奖生命周期，<code>StartLiveLottery</code> 返回连接结果</td></tr><tr><td><code>DrawWinners</code> / <code>GetParticipantCount</code> / <code>IsLiveLotteryRunning</code></td><td>live</td><td>开奖、人数、运行态</td></tr><tr><td><code>GetLastHistoryError</code> / <code>CopyText</code></td><td>live</td><td>历史写入错误、原生剪贴板</td></tr><tr><td><code>WatchDanmaku</code> / <code>StopDanmaku</code> / <code>GetDanmakuFeed</code> / <code>GetEmoteMap</code></td><td>danmaku</td><td>实时弹幕面板</td></tr><tr><td><code>GetRoomInfo</code> / <code>GetRoomPlayURL</code></td><td>room</td><td>房间元信息与 HLS 地址</td></tr><tr><td><code>GetProfiles</code> / <code>SwitchProfile</code> / <code>CreateProfile</code> / <code>DeleteProfile</code> / <code>RenameProfile</code></td><td>profile</td><td>配置管理</td></tr><tr><td><code>SaveProfileConfig</code> / <code>SetBackgroundImage</code> / <code>GetBackgroundImage</code></td><td>profile</td><td>口令、人数、背景</td></tr><tr><td><code>AddWatchedRoom</code> / <code>RemoveWatchedRoom</code> / <code>GetWatchedRooms</code></td><td>profile</td><td>频道管理</td></tr><tr><td><code>GetHistory</code> / <code>DeleteHistory</code> / <code>DeleteAllHistory</code> / <code>ExportHistory</code></td><td>history</td><td>历史读取、删除、导出</td></tr></tbody></table><p>返回复杂结构的方法统一返回 JSON 字符串，前端 <code>parseJSON</code> 解析；这也是两条通道能共用同一份前端 API 封装的原因。</p>',20))])}const g=n(E,[["render",A]]);export{f as __pageData,g as default};
